interface UserPreferences {
  theme: string
  language: string
  email: string
  notifications: boolean
}

// User-specific data that changes on each request, so opt out of caching.
async function getUserPreferences(): Promise<UserPreferences> {
  try {
    const res = await fetch('https://api.example.com/user/preferences', {
      cache: 'no-store',
    })
    return res.json()
  } catch {
    // Return fallback data when the request fails
    return {
      theme: 'system',
      language: 'en',
      email: 'guest@example.com',
      notifications: false,
    }
  }
}

export default async function UserDashboard() {
  const preferences = await getUserPreferences()

  return (
    <div>
      <h2>User Dashboard</h2>
      <ul>
        <li>Theme: {preferences.theme}</li>
        <li>Language: {preferences.language}</li>
        <li>Email: {preferences.email}</li>
        <li>Notifications: {preferences.notifications ? 'on' : 'off'}</li>
      </ul>
    </div>
  )
}
